import { EspLogLevel, ParsedLogLine } from '../types/serial';

// Remove ANSI color escape sequences generated by ESP-IDF log module
export function stripAnsi(text: string): string {
  // eslint-disable-next-line no-control-regex
  return text.replace(/\x1B\[[0-9;]*[a-zA-Z]/g, '').replace(/[\x00-\x08\x0B-\x0C\x0E-\x1F]/g, '');
}

// Known ESP32 Reset Reasons
export const ESP_RESET_REASONS: Record<string, { label: string; desc: string; severity: 'info' | 'warning' | 'error' }> = {
  '0x1': { label: 'POWERON_RESET', desc: '電源投入またはVdd正常立ち上がりによる通常起動', severity: 'info' },
  '0x3': { label: 'SW_RESET', desc: 'ソフトウェアによる再起動 (esp_restart())', severity: 'info' },
  '0x4': { label: 'OWDT_RESET', desc: 'Legacy Watchdog Timer によるリセット', severity: 'error' },
  '0x5': { label: 'DEEPSLEEP_RESET', desc: 'Deep-Sleep からの復帰', severity: 'info' },
  '0x6': { label: 'SDIO_RESET', desc: 'SDIOスレーブからのリセット', severity: 'info' },
  '0x7': { label: 'TG0WDT_SYS_RESET', desc: 'Timer Group 0 Watchdog によるシステムリセット (タスクがCPUを長時間占有)', severity: 'error' },
  '0x8': { label: 'TG1WDT_SYS_RESET', desc: 'Timer Group 1 Watchdog によるシステムリセット', severity: 'error' },
  '0x9': { label: 'RTCWDT_SYS_RESET', desc: 'RTC Watchdog によるシステムリセット', severity: 'error' },
  '0xa': { label: 'INTRUSION_RESET', desc: '侵入検知リセット', severity: 'warning' },
  '0xb': { label: 'TGWDT_CPU_RESET', desc: 'Timer Group Watchdog によるCPUリセット', severity: 'error' },
  '0xc': { label: 'SW_CPU_RESET', desc: 'ソフトウェアCPUリセット', severity: 'info' },
  '0xd': { label: 'RTCWDT_CPU_RESET', desc: 'RTC Watchdog によるCPUリセット', severity: 'error' },
  '0xe': { label: 'EXT_CPU_RESET', desc: '外部ピン(PRO_CPU)によるCPUリセット', severity: 'warning' },
  '0xf': { label: 'BROWNOUT_RESET', desc: '電源電圧低下(Brownout)リセット。給電能力不足や急激な負荷電流が原因', severity: 'error' },
  '0x10': { label: 'RTCWDT_BROWN_OUT_RESET', desc: 'RTC Brownout リセット', severity: 'error' },
  '0x11': { label: 'RTCWDT_RTC_RESET', desc: 'RTC Watchdog によるRTCリセット', severity: 'error' },
};

// Known Guru Meditation Error Causes
export const GURU_MEDITATION_CAUSES: Record<string, string> = {
  LoadProhibited: '読み取り禁止アドレスへのアクセス (NULLポインタ等の不正メモリアクセス)',
  StoreProhibited: '書き込み禁止アドレスへのアクセス (const定数領域への書き込みや不正ポインタ)',
  InstrFetchProhibited: '実行禁止アドレスからの命令フェッチ (関数ポインタ破壊やメモリ破壊)',
  IllegalInstruction: '未定義または不正なCPU命令の実行 (不正なジャンプ先、コンパイラターゲット不一致)',
  IntegerDivideByZero: 'ゼロ除算エラー',
  'Stack canary watchpoint got triggered': 'FreeRTOSタスクのスタックオーバーフロー (スタックサイズ不足)',
  'Interrupt wdt timeout': '割り込みハンドラ(ISR)のタイムアウト (ISR内で長時間ブロック処理を実行)',
  'Unhandled debug exception': '未処理のデバッグ例外 (ブレークポイントまたはウォッチポイント)',
  DoubleExceptionVector: '二重例外 (例外ハンドラ実行中にさらなる例外が発生)',
};

/**
 * Regex for standard ESP-IDF log lines:
 * e.g., "I (1234) wifi: connected to ap"
 * Captures:
 * 1: Level (E, W, I, D, V)
 * 2: Timestamp (e.g. 1234)
 * 3: Tag (e.g. wifi)
 * 4: Message (e.g. connected to ap)
 */
const ESP_LOG_REGEX = /^([EWIDV])\s+\((\d+)\)\s+([^:]+):\s*(.*)$/;

/**
 * Parse a raw text line received from ESP32 serial into a structured ParsedLogLine
 */
export function parseEspLogLine(rawInput: string, index: number): ParsedLogLine {
  const cleanLine = stripAnsi(rawInput).trimEnd();
  const id = `log_${Date.now()}_${index}_${Math.random().toString(36).substring(2, 6)}`;
  const now = new Date();

  // Check for Guru Meditation Error
  const isGuru = /Guru Meditation Error/i.test(cleanLine);
  const isPanic = isGuru || /panic'ed/i.test(cleanLine) || /Backtrace:/i.test(cleanLine) || /abort\(\) was called/i.test(cleanLine);
  
  // Check for Reset Reasons
  const isReset = /rst:(0x[0-9a-fA-F]+)/i.test(cleanLine) || /boot:(0x[0-9a-fA-F]+)/i.test(cleanLine) || /Rebooting\.\.\./i.test(cleanLine);
  const isBrownout = /Brownout detector was triggered/i.test(cleanLine);

  let errorCategory: string | undefined;

  if (isGuru) {
    for (const [key, desc] of Object.entries(GURU_MEDITATION_CAUSES)) {
      if (cleanLine.includes(key)) {
        errorCategory = `Guru Meditation: ${key} (${desc})`;
        break;
      }
    }
    if (!errorCategory) {
      errorCategory = 'Guru Meditation Error (CPU Panic)';
    }
  } else if (isBrownout) {
    errorCategory = 'Brownout Detector (電源電圧ドロップ)';
  } else if (/rst:(0x[0-9a-fA-F]+)/i.test(cleanLine)) {
    const match = cleanLine.match(/rst:(0x[0-9a-fA-F]+)/i);
    if (match && match[1]) {
      const code = match[1].toLowerCase();
      const reason = ESP_RESET_REASONS[code];
      if (reason) {
        errorCategory = `リセット要因: ${reason.label} - ${reason.desc}`;
      } else {
        errorCategory = `リセット要因: ${match[1]}`;
      }
    }
  }

  // Test against standard ESP-IDF log format
  const match = cleanLine.match(ESP_LOG_REGEX);

  if (match) {
    const levelChar = match[1] as EspLogLevel;
    const timestamp = match[2];
    const tag = match[3].trim();
    const message = match[4];

    const isError = levelChar === 'E' || isPanic || isBrownout;
    const isWarning = levelChar === 'W';

    return {
      id,
      raw: cleanLine,
      level: levelChar,
      timestamp,
      tag,
      message,
      receivedAt: now,
      isError,
      isWarning,
      isReset,
      isPanic,
      errorCategory,
    };
  }

  // Not matching standard ESP-IDF line: check if it's ROM bootloader or panic output
  let specialLevel: EspLogLevel = 'RAW';
  let isError = false;
  let isWarning = false;

  if (isPanic || isBrownout || cleanLine.startsWith('abort()')) {
    specialLevel = 'PANIC';
    isError = true;
  } else if (isReset || cleanLine.startsWith('configsip:') || cleanLine.startsWith('clk_drv:') || cleanLine.startsWith('load:0x') || cleanLine.startsWith('entry 0x')) {
    specialLevel = 'BOOT';
    if (/rst:0x[789f]/i.test(cleanLine)) {
      isError = true; // WDT or Brownout reset
    }
  } else if (/error/i.test(cleanLine) || /failed/i.test(cleanLine) || /assert failed/i.test(cleanLine)) {
    specialLevel = 'E';
    isError = true;
  } else if (/warn/i.test(cleanLine)) {
    specialLevel = 'W';
    isWarning = true;
  }

  return {
    id,
    raw: cleanLine,
    level: specialLevel,
    timestamp: null,
    tag: specialLevel === 'BOOT' ? 'bootloader' : specialLevel === 'PANIC' ? 'panic' : null,
    message: cleanLine,
    receivedAt: now,
    isError,
    isWarning,
    isReset,
    isPanic,
    errorCategory,
  };
}
